const topCategoriesForUser = `-- name: TopCategoriesForUser :many
SELECT c.id, c.color, c.icon, COALESCE(ct.name, ctf.name) AS name,
  d.id AS domain_id, d.color AS domain_color,
  s.mastery::int AS mastery, s.answered::int AS answered
FROM user_category_stats s
JOIN categories c ON c.id = s.category_id
JOIN domains d    ON d.id = c.domain_id
LEFT JOIN category_translations ct  ON ct.category_id = c.id AND ct.lang = $1
LEFT JOIN category_translations ctf ON ctf.category_id = c.id AND ctf.lang = 'en'
WHERE s.user_id = $2 AND s.answered > 0
  AND (NOT $3::boolean OR d.family = 'islamic')
ORDER BY CASE WHEN $4::boolean THEN s.mastery END ASC,
         CASE WHEN NOT $4::boolean THEN s.mastery END DESC,
         s.answered DESC
LIMIT $5
`

type TopCategoriesForUserParams struct {
	Lang        string    `json:"lang"`
	UserID      uuid.UUID `json:"user_id"`
	IslamicOnly bool      `json:"islamic_only"`
	Weakest     bool      `json:"weakest"`
	Lim         int32     `json:"lim"`
}

type TopCategoriesForUserRow struct {
	ID          int64  `json:"id"`
	Color       string `json:"color"`
	Icon        string `json:"icon"`
	Name        string `json:"name"`
	DomainID    int64  `json:"domain_id"`
	DomainColor string `json:"domain_color"`
	Mastery     int32  `json:"mastery"`
	Answered    int32  `json:"answered"`
}

// Profile: strongest and weakest categories across the player's domains.
func (q *Queries) TopCategoriesForUser(ctx context.Context, arg TopCategoriesForUserParams) ([]TopCategoriesForUserRow, error) {
	rows, err := q.db.Query(ctx, topCategoriesForUser,
		arg.Lang,
		arg.UserID,
		arg.IslamicOnly,
		arg.Weakest,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TopCategoriesForUserRow{}
	for rows.Next() {
		var i TopCategoriesForUserRow
		if err := rows.Scan(
			&i.ID,
			&i.Color,
			&i.Icon,
			&i.Name,
			&i.DomainID,
			&i.DomainColor,
			&i.Mastery,
			&i.Answered,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertAchievementProgress = `-- name: UpsertAchievementProgress :exec
INSERT INTO user_achievements (user_id, achievement_id, progress, unlocked_at)
SELECT $1, a.id, $2,
       CASE WHEN $2::int >= a.target THEN now() END
FROM achievements a WHERE a.code = $3
ON CONFLICT (user_id, achievement_id) DO UPDATE SET
  progress    = GREATEST(user_achievements.progress, EXCLUDED.progress),
  unlocked_at = COALESCE(user_achievements.unlocked_at, EXCLUDED.unlocked_at)
`

type UpsertAchievementProgressParams struct {
	UserID   uuid.UUID `json:"user_id"`
	Progress int32     `json:"progress"`
	Code     string    `json:"code"`
}

func (q *Queries) UpsertAchievementProgress(ctx context.Context, arg UpsertAchievementProgressParams) error {
	_, err := q.db.Exec(ctx, upsertAchievementProgress, arg.UserID, arg.Progress, arg.Code)
	return err
}
